function UIFishPoolLevelOfFishDialog:Awake()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.controller.gameObject.transform:Find("ImgBlack"), Bind(self, self.OnBtnClose))
    SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnDetails))

