function UIFishPoolLevelOfFishDialog:FillSelf()
    self:FillLevelInfo()
    self:FillFishingInfos()
    self:FillLevelAdditionInfo()
end

--绘制i等级信息
function UIFishPoolLevelOfFishDialog:FillLevelInfo()
    local level, exp = FishingUtils.GetCurLevelAndExp()
    local showExp = FishingUtils.GetCurShowExp()
    local needExp = FishingUtils.GetUpLevelExp(level)
    CfUtils.FillText(self.TxtLevel2, level)

    if needExp then
        CfUtils.FillText(self.TxtNum, "<color=#ff41b7>"..showExp.."</color>/"..needExp)

        --KTool.SetActive(self.RotateArea, true)
        self.Fill.fillAmount = showExp/needExp--0.15 + showExp/needExp * (0.84 - 0.15) 
        --local ang = 360 * (0.15 + showExp/needExp * (0.84 - 0.15)) 
        --self.RotateArea.transform.localRotation = Quaternion.Euler(0, 0, -ang)

        KTool.SetActive(self.TextMax, false)
        KTool.SetActive(self.TxtNum, true)
    else
        self.Fill.fillAmount = 1
        KTool.SetActive(self.TextMax, true)
        KTool.SetActive(self.TxtNum, false)
    end
end

--绘制钓鱼信息
function UIFishPoolLevelOfFishDialog:FillFishingInfos()
    local t = {
        {
            desc = localize("钓鱼总数"),
            num = fishingComponent:GetFishTotal(),
            str = localize("次")
        },
        {
            desc = localize("图鉴收集"),
            num = fishingComponent:GetFishCollectedNum(),
            str = localize("条")
        },
        {
            desc = localize("抛竿良好"),
            num = fishingComponent:GetCastingGoodNum(),
            str = localize("次")
        },
        {
            desc = localize("抛竿完美"),
            num = fishingComponent:GetCastingPerfectNum(),
            str = localize("次")
        },
        {
            desc = localize("脱线"),
            num = fishingComponent:GetFishEscapeNum(),
            str = localize("次")
        },
        {
            desc = localize("断线"),
            num = fishingComponent:GetCutOffFishNum(),
            str = localize("次")
        },
    }
    for k, v in pairs(t) do
        local go = CfUtils.InstantiateGo(self.FishRecord, self.Content)
        self:FillFishingInfo(go, v, k)
    end
end

function UIFishPoolLevelOfFishDialog:FillFishingInfo(go, data, ind)
    if not go or not data then
        return
    end
    CfUtils.FillText(go.transform:Find("TextRecord"), data.desc)
    CfUtils.FillText(go.transform:Find("TxtNumber"), data.num)
    KTool.SetActive(go.transform:Find("ImgBg"), ((ind % 2) == 0))
    KTool.SetActive(go, true)
end

--绘制等级加成信息
function UIFishPoolLevelOfFishDialog:FillLevelAdditionInfo()
    local curLevel = FishingUtils.GetCurLevelAndExp()

    local t = {}
    local additionData = FishingUtils.GetLevelAddition(curLevel)
    for k, v in pairs(additionData) do
        table.insert(t, {
            desc = FishingUtils.GetAdditionDesc(v, true),
            num = checkInt(v.value *100).."%" 
        })
    end

    local data = t[1]
    CfUtils.FillText(self.TxtAddition, data.desc)
    CfUtils.FillText(self.TxtNumber, "+"..data.num)
end

function UIFishPoolLevelOfFishDialog:OnBtnDetails()
    local curLevel = FishingUtils.GetCurLevelAndExp()
    local nextLevel = FishingUtils.GetNextLevel(curLevel)
    local desc = ""
    if not nextLevel then
        desc = localize("已是最大加成")
    else
        local additionData = FishingUtils.GetLevelAddition(nextLevel)
        for k, v in pairs(additionData) do
            desc = desc..FishingUtils.GetAdditionDesc(v, true)..checkInt(v.value *100).."%"  .."\n"
        end
    end
    GameUtils.ShowCommonTipsBoard(self.BtnDetails, localize("下一等级:"), desc)
end

function UIFishPoolLevelOfFishDialog:OnBtnClose()
    UIModule.CloseDialog(self.controller)
end

